;
; CONWAY'S GAME OF LIFE / "CONWAY MULTIVERSE" -- NATIVE-CASM ENTRY MODULE.
; FULLY SELF-CONTAINED: NO CA65 BUILD, NO .SEGMENT, NO .IMPORT/.EXPORT, NO
; .DEFINE, NO SHARED .INC. CONSTANTS ARE DEFINED INLINE BELOW (NOT
; .INCLUDE'D -- CASM 0.6.2 EMITS 3-BYTE ABSOLUTE FOR A ZP-VALUED CONSTANT
; READ FROM AN .INCLUDE'D FILE). SEE THE 2026-09-03 CONWAY CASM-NATIVE
; MIGRATION PLAN.
;
; THE GRID / DRAWING HALF IS TEXTUALLY .INCLUDE'D AT THE END
; (CONWAYGRID.S), ALONG WITH TWO BUILD-GENERATED SOURCES:
;   CONWAYVER.S   -- EXITBANNER (PETSCII, VIA CHROUT) + MENUVERSION
;                    (SCREEN-CODE) + MENU_VERSION_LEN. FROM CONWAY_VERSION
;                    + BUILD_CONWAY VIA GEN_CONWAY_VERSION.PY.
;   CONWAYMENU.S  -- ALL MENU / SIMULATION-STATUS TEXT AS SCREEN-CODE .BYTE
;                    DATA (WAS CA65 "SCREENCODE_MIXED" .CHARMAP MACROS) +
;                    STATUS_TEXT_LEN / MENU_NONE_LEN. VIA GEN_CONWAY_MENU.PY.
;
; THE ABOUT 23 COMPILE-TIME .ASSERT LAYOUT GUARDS THE CA65 SOURCE CARRIED ARE
; RE-CHECKED HOST-SIDE BY SCRIPTS/CHECK_CONWAY_LAYOUT.PY (CASM .ASSERT IS
; TRUTHINESS-ONLY, NO <=).
;
; CASM ALWAYS EMITS AT $3400 WITH A 2-BYTE CBM LOAD HEADER; NO .ORG NEEDED.
; THE APP IS R6-RELOCATABLE -- THE SHELL'S SDEXT LOADER RELOCATES IT TO
; USERPROGSTART BEFORE EXECUTION.

; ===========================================================================
; INLINE CONSTANTS  (HAND-DERIVED; CROSS-CHECKED AGAINST THE RETIRED
; COMMON.INC + INCLUDE/CA65/COMMAND64.INC, NOT COPIED)
; ===========================================================================

; --- KERNAL JUMP TABLE ($FFXX) ---------------------------------------------
KERNALCHROUT = $FFD2       ; OUTPUT A CHARACTER TO THE CURRENT CHANNEL
KERNALGETIN  = $FFE4       ; RAW KEYBOARD INPUT (NO SCREEN EDITOR)

; --- PETSCII --------------------------------------------------------------
PETCR        = $0D

; --- GRID / SCREEN GEOMETRY ----------------------------------------------
; COMMON.INC DEFINED SOME OF THESE AS N*GRID_W+K; CASM NAMED-CONSTANT RHS
; MUST BE A BARE LITERAL, SO THEY ARE PRE-COMPUTED HERE (ARITHMETIC SHOWN,
; RE-VERIFIED BY CHECK_CONWAY_LAYOUT.PY).
GRID_W                  = 40
GRID_H                  = 24
GRID_SIZE               = 960
STATUS_ROW_OFFSET       = 960
MENU_PROMPT_OFFSET      = 920      ; 23 * GRID_W
MENU_BIRTH_FIELD_OFFSET = 612      ; 15 * GRID_W + 12
MENU_SURV_FIELD_OFFSET  = 652      ; 16 * GRID_W + 12
GEN_LABEL_OFFSET        = 991      ; STATUS_ROW_OFFSET + 31
GEN_DIGITS_OFFSET       = 995      ; STATUS_ROW_OFFSET + 35
PAUSE_TEXT_OFFSET       = 963      ; STATUS_ROW_OFFSET + 3
PAUSE_TEXT_LEN          = 5

; --- HARDWARE ------------------------------------------------------------
VIC_BORD  = $D020
VIC_BGND  = $D021
SCREEN    = $0400
COLORRAM  = $D800
JIFFY_CLK = $A2

; --- DISPLAY -----------------------------------------------------------
CHAR_LIVE  = $A0
CHAR_DEAD  = $20
CLR_LIVE   = 5
CLR_PAUSED = 3

; --- TIMING ----------------------------------------------------------
GEN_DELAY = 3

; --- UI STATE VALUES ------------------------------------------------
MENU_STATE_NORMAL   = 0
MENU_STATE_BIRTH    = 1
MENU_STATE_SURVIVAL = 2
PRESET_CUSTOM       = $FF
PRESET_COUNT        = 9
RULE_COUNT          = 9

; --- TEXT-LENGTH CONSTANTS ----------------------------------------------
; MUST BE INLINE HERE, NOT IN THE .INCLUDE'D CONWAYMENU.S / CONWAYVER.S:
; CASM 0.6.2 TREATS A NAMED CONSTANT DEFINED IN AN .INCLUDE'D FILE AS A
; RELOCATABLE SYMBOL, EMITTING SPURIOUS R6 ENTRIES FOR EVERY OPERAND (EVEN
; IMMEDIATES) THAT REFERENCES IT. THESE MATCH THE GENERATED STRING LENGTHS;
; CHECK_CONWAY_LAYOUT.PY RE-VERIFIES BOTH SIDES.
MENU_NONE_LEN    = 4       ; LEN("NONE")
STATUS_TEXT_LEN  = 40      ; LEN(STATUSTEXT), FILLS THE 40-COLUMN ROW
MENU_VERSION_LEN = 10      ; LEN("0.4.1.1063")

; --- ZERO PAGE ($70-$82, APP-PRIVATE EXTERNAL-PROGRAM AREA) --------
; INLINE (NOT .INCLUDE'D) SO CASM KEEPS ZERO-PAGE ADDRESSING.
ZPPREVLO    = $70
ZPPREVHI    = $71
ZPCURRLO    = $72
ZPCURRHI    = $73
ZPNEXTLO    = $74
ZPNEXTHI    = $75
ZPDSTLO     = $76
ZPDSTHI     = $77
ZPROW       = $78
ZPCOL       = $79
ZPCOUNT     = $7A
ZPLFSR      = $7B
ZPPAUSED    = $7C
ZPBUFSEL    = $7D
ZPINMENU    = $7E
ZPMENUSTATE = $7F
ZPPRESETIDX = $80
ZPGENLO     = $81
ZPGENHI     = $82

; ===========================================================================
; ENTRY POINT
; ===========================================================================
START:
    LDA $D012
    EOR JIFFY_CLK
    EOR $0314
    ORA #1
    STA ZPLFSR

    LDA #0
    STA ZPPAUSED
    STA ZPBUFSEL
    STA ZPINMENU
    STA ZPMENUSTATE
    JSR RESETGENERATION

    ; ALWAYS INITIALIZE THE ACTIVE RULE TABLES BEFORE COMPUTENEXT CAN RUN.
    ; PRESET 0 IS CONWAY'S ORIGINAL B3/S23 BEHAVIOR.
    LDA #0
    JSR LOADPRESET

    STA VIC_BORD
    STA VIC_BGND

    LDA #CLR_LIVE
    LDX #0
@FILLCOLORPAGES:
    STA COLORRAM,     X
    STA COLORRAM+256, X
    STA COLORRAM+512, X
    INX
    BNE @FILLCOLORPAGES
    LDY #0
@FILLCOLORTAIL:
    STA COLORRAM+768, Y
    INY
    CPY #232
    BNE @FILLCOLORTAIL

    JSR RANDOMIZEGRID
    JSR ENTERMENU

; ---------------------------------------------------------------------------
; MAIN LOOP
; ---------------------------------------------------------------------------
MAINLOOP:
    JSR HANDLEKEYS

    LDA ZPINMENU
    BNE MAINLOOP
    LDA ZPPAUSED
    BNE MAINLOOP

    JSR WAITDELAY
    JSR COMPUTENEXT
    JSR SWAPBUFS
    JSR INCREMENTGENERATION
    JSR DRAWGRID
    JSR DRAWGENERATIONCOUNTER
    JMP MAINLOOP

; ---------------------------------------------------------------------------
; HANDLEKEYS -- NON-BLOCKING DISPATCHER FOR MENU AND SIMULATION STATES.
; EXIT PATHS JMP DIRECTLY TO EXITTOSHELL SO ONLY THIS ROUTINE'S RETURN
; ADDRESS IS DISCARDED BEFORE RTS RESUMES THE SHELL'S ORIGINAL JSR CALLER.
; ---------------------------------------------------------------------------
HANDLEKEYS:
    JSR KERNALGETIN
    BEQ @NONE

    LDX ZPINMENU
    BEQ HANDLESIMULATIONKEY
    JMP HANDLEMENUKEY
@NONE:
    RTS

HANDLESIMULATIONKEY:
    CMP #3                      ; RUN/STOP
    BEQ @EXIT
    CMP #$51                    ; Q -> MENU
    BEQ @MENU
    CMP #$20                    ; SPACE
    BEQ @PAUSE
    CMP #$52                    ; R
    BEQ @RANDOM
    CMP #$43                    ; C
    BEQ @CLEAR
    RTS
@EXIT:
    JMP EXITTOSHELL
@MENU:
    JMP ENTERMENU
@PAUSE:
    LDA ZPPAUSED
    EOR #$FF
    STA ZPPAUSED
    JSR DRAWPAUSECOLOR
    RTS
@RANDOM:
    JSR RANDOMIZEGRID
    JSR RESETGENERATION
    JSR DRAWGRID
    JSR DRAWGENERATIONCOUNTER
    JSR DRAWPAUSECOLOR
    RTS
@CLEAR:
    JSR CLEARGRID
    JSR RESETGENERATION
    LDA #$FF
    STA ZPPAUSED
    JSR DRAWGRID
    JSR DRAWGENERATIONCOUNTER
    JSR DRAWPAUSECOLOR
    RTS

HANDLEMENUKEY:
    LDX ZPMENUSTATE
    BNE HANDLEMENUEDITKEY

    CMP #3                      ; RUN/STOP
    BEQ @EXIT
    CMP #$51                    ; Q
    BEQ @EXIT
    CMP #$0D                    ; RETURN
    BEQ @STARTSIM
    CMP #$52                    ; R: RANDOMIZE AND START
    BEQ @RANDOMSTART
    CMP #$42                    ; B: EDIT BIRTH
    BEQ @BIRTH
    CMP #$53                    ; S: EDIT SURVIVAL
    BEQ @SURVIVAL
    CMP #$31                    ; '1'
    BCC @IGNORE
    CMP #$3A                    ; ONE PAST '9'
    BCS @IGNORE
    SEC
    SBC #$31
    JSR LOADPRESET
    JMP DRAWMENUDYNAMICS
@IGNORE:
    RTS
@EXIT:
    JMP EXITTOSHELL
@STARTSIM:
    JMP STARTSIMULATION
@RANDOMSTART:
    JSR RANDOMIZEGRID
    JMP STARTSIMULATION
@BIRTH:
    LDA #MENU_STATE_BIRTH
    STA ZPMENUSTATE
    JMP DRAWMENUPROMPT
@SURVIVAL:
    LDA #MENU_STATE_SURVIVAL
    STA ZPMENUSTATE
    JMP DRAWMENUPROMPT

HANDLEMENUEDITKEY:
    CMP #$30                    ; '0'
    BCC @CANCEL
    CMP #$39                    ; ONE PAST '8'
    BCS @CANCEL
    SEC
    SBC #$30
    TAX
    LDA ZPMENUSTATE
    CMP #MENU_STATE_BIRTH
    BEQ @TOGGLEBIRTH
    JSR TOGGLESURVIVAL
    JMP @FINISH
@TOGGLEBIRTH:
    JSR TOGGLEBIRTH
@FINISH:
    LDA #MENU_STATE_NORMAL
    STA ZPMENUSTATE
    JSR DRAWMENUDYNAMICS
    JMP DRAWMENUPROMPT
@CANCEL:
    LDA #MENU_STATE_NORMAL
    STA ZPMENUSTATE
    JSR DRAWMENUDYNAMICS
    JMP DRAWMENUPROMPT

; PRECONDITION: REACHED BY JMP FROM HANDLEKEYS DISPATCH, NEVER NESTED JSR.
EXITTOSHELL:
    LDA #0
    STA VIC_BORD
    STA VIC_BGND
    JSR CLEARSCREEN
    LDA #$13                    ; HOME CURSOR BEFORE PRINTING EXIT BANNER
    JSR KERNALCHROUT
    LDA #<EXITBANNER
    LDY #>EXITBANNER
    JSR PRINTSTRING
    PLA
    PLA
    RTS

ENTERMENU:
    LDA #$FF
    STA ZPINMENU
    LDA #MENU_STATE_NORMAL
    STA ZPMENUSTATE
    JSR DRAWMENU
    RTS

STARTSIMULATION:
    LDA #0
    STA ZPINMENU
    STA ZPMENUSTATE
    STA ZPPAUSED
    JSR RESETGENERATION
    JSR DRAWGRID
    JSR DRAWSIMULATIONSTATUS
    RTS

; ---------------------------------------------------------------------------
; RESETGENERATION -- RESET THE 16-BIT GENERATION COUNT WITHOUT SCREEN I/O.
; CLOBBERS: A, N, Z.
; ---------------------------------------------------------------------------
RESETGENERATION:
    LDA #0
    STA ZPGENLO
    STA ZPGENHI
    RTS

; ---------------------------------------------------------------------------
; INCREMENTGENERATION -- INCREMENT MODULO 65536 AFTER A COMPLETED GENERATION.
; PRESERVES: A, X, Y. CLOBBERS: N, Z.
; ---------------------------------------------------------------------------
INCREMENTGENERATION:
    INC ZPGENLO
    BNE @DONE
    INC ZPGENHI
@DONE:
    RTS

; ---------------------------------------------------------------------------
; DRAWMENU -- RENDER COMPACT STATIC LINES, ACTIVE PRESET/RULES, AND PROMPT.
; CLOBBERS: A, X, Y, N, Z, C AND ZPCURR/ZPDST POINTER PAIRS.
; ---------------------------------------------------------------------------
DRAWMENU:
    JSR CLEARMENUAREA
    LDA #0
    STA MENUDESCIDX

@DESCLOOP:
    LDX MENUDESCIDX
    LDA MENUDESCRIPTORS, X
    STA ZPCURRLO
    INX
    LDA MENUDESCRIPTORS, X
    STA ZPCURRHI
    ORA ZPCURRLO
    BEQ @DESCDONE
    INX
    LDA MENUDESCRIPTORS, X
    STA ZPDSTLO
    INX
    LDA MENUDESCRIPTORS, X
    STA ZPDSTHI
    INX
    STX MENUDESCIDX
    JSR COPYMENUSTRING
    JMP @DESCLOOP

@DESCDONE:
    JSR DRAWMENUDYNAMICS
    JMP DRAWMENUPROMPT

; CLEAR ALL 25 ROWS SO NO SIMULATION STATUS/COLOR TEXT REMAINS BELOW THE MENU.
CLEARMENUAREA:
    LDA #<SCREEN
    STA ZPDSTLO
    LDA #>SCREEN
    STA ZPDSTHI
    LDA #CHAR_DEAD
    LDX #0
    LDY #0
@PAGE:
    STA (ZPDSTLO), Y
    INY
    BNE @PAGE
    INC ZPDSTHI
    INX
    CPX #3
    BNE @PAGE
    LDY #0
@TAIL:
    STA (ZPDSTLO), Y
    INY
    CPY #232
    BNE @TAIL
    RTS

; COPY A NULL-TERMINATED SCREEN-CODE STRING FROM ZPCURR TO ZPDST.
COPYMENUSTRING:
    LDY #0
@LOOP:
    LDA (ZPCURRLO), Y
    BEQ @DONE
    STA (ZPDSTLO), Y
    INY
    BNE @LOOP
@DONE:
    RTS

DRAWMENUDYNAMICS:
    JSR DRAWPRESETARROW
    JSR DRAWBIRTHSUMMARY
    JMP DRAWSURVIVALSUMMARY

DRAWPRESETARROW:
    LDA #CHAR_DEAD
    LDX #0
@CLEARLOOP:
    LDY #0
    LDA MENUARROWLO, X
    STA ZPDSTLO
    LDA MENUARROWHI, X
    STA ZPDSTHI
    LDA #CHAR_DEAD
    STA (ZPDSTLO), Y
    INX
    CPX #PRESET_COUNT
    BNE @CLEARLOOP

    LDA ZPPRESETIDX
    CMP #PRESET_COUNT
    BCS @DONE
    TAX
    LDA MENUARROWLO, X
    STA ZPDSTLO
    LDA MENUARROWHI, X
    STA ZPDSTHI
    LDY #0
    LDA #$3E
    STA (ZPDSTLO), Y
@DONE:
    RTS

DRAWBIRTHSUMMARY:
    LDY #RULE_COUNT - 1
    LDA #CHAR_DEAD
@CLEAR:
    STA SCREEN + MENU_BIRTH_FIELD_OFFSET, Y
    DEY
    BPL @CLEAR
    LDX #0
    LDY #0
@RULELOOP:
    JSR GETBIRTHRULE
    BEQ @NEXTRULE
    TXA
    CLC
    ADC #$30
    STA SCREEN + MENU_BIRTH_FIELD_OFFSET, Y
    INY
@NEXTRULE:
    INX
    CPX #RULE_COUNT
    BNE @RULELOOP
    CPY #0
    BNE @DONE
    LDX #0
@NONELOOP:
    LDA MENUNONETEXT, X
    STA SCREEN + MENU_BIRTH_FIELD_OFFSET, X
    INX
    CPX #MENU_NONE_LEN
    BNE @NONELOOP
@DONE:
    RTS

DRAWSURVIVALSUMMARY:
    LDY #RULE_COUNT - 1
    LDA #CHAR_DEAD
@CLEAR:
    STA SCREEN + MENU_SURV_FIELD_OFFSET, Y
    DEY
    BPL @CLEAR
    LDX #0
    LDY #0
@RULELOOP:
    JSR GETSURVIVALRULE
    BEQ @NEXTRULE
    TXA
    CLC
    ADC #$30
    STA SCREEN + MENU_SURV_FIELD_OFFSET, Y
    INY
@NEXTRULE:
    INX
    CPX #RULE_COUNT
    BNE @RULELOOP
    CPY #0
    BNE @DONE
    LDX #0
@NONELOOP:
    LDA MENUNONETEXT, X
    STA SCREEN + MENU_SURV_FIELD_OFFSET, X
    INX
    CPX #MENU_NONE_LEN
    BNE @NONELOOP
@DONE:
    RTS

DRAWMENUPROMPT:
    LDX #39
    LDA #CHAR_DEAD
@CLEAR:
    STA SCREEN + MENU_PROMPT_OFFSET, X
    DEX
    BPL @CLEAR

    LDA ZPMENUSTATE
    CMP #MENU_STATE_BIRTH
    BEQ @BIRTH
    CMP #MENU_STATE_SURVIVAL
    BEQ @SURVIVAL
    LDA #<MENUPROMPTNORMAL
    LDY #>MENUPROMPTNORMAL
    JMP @COPY
@BIRTH:
    LDA #<MENUPROMPTBIRTH
    LDY #>MENUPROMPTBIRTH
    JMP @COPY
@SURVIVAL:
    LDA #<MENUPROMPTSURVIVAL
    LDY #>MENUPROMPTSURVIVAL
@COPY:
    STA ZPCURRLO
    STY ZPCURRHI
    LDA #<(SCREEN + MENU_PROMPT_OFFSET)
    STA ZPDSTLO
    LDA #>(SCREEN + MENU_PROMPT_OFFSET)
    STA ZPDSTHI
    JSR COPYMENUSTRING

    ; KEEP THE FULL RELEASE/BUILD VERSION RIGHT-ALIGNED AFTER EVERY PROMPT
    ; REDRAW. CHECK_CONWAY_LAYOUT.PY GUARANTEES A BLANK SEPARATOR AFTER THE
    ; LONGEST PROMPT AND KEEPS THE FINAL BYTE INSIDE ROW 23.
    LDX #0
@VERSIONLOOP:
    LDA MENUVERSION, X
    STA SCREEN + MENU_PROMPT_OFFSET + GRID_W - MENU_VERSION_LEN, X
    INX
    CPX #MENU_VERSION_LEN
    BNE @VERSIONLOOP
    RTS

; ---------------------------------------------------------------------------
; WAITDELAY -- BUSY-WAIT FOR GEN_DELAY JIFFY-CLOCK INCREMENTS.
; ---------------------------------------------------------------------------
WAITDELAY:
    LDA #GEN_DELAY
@OUTER:
    PHA
    LDA JIFFY_CLK
@POLL:
    CMP JIFFY_CLK
    BEQ @POLL
    PLA
    SEC
    SBC #1
    BNE @OUTER
    RTS

; ---------------------------------------------------------------------------
; SWAPBUFS -- TOGGLE ZPBUFSEL; ROLES OF GRID0 AND GRID1 EXCHANGE.
; ---------------------------------------------------------------------------
SWAPBUFS:
    LDA ZPBUFSEL
    EOR #1
    STA ZPBUFSEL
    RTS

; ---------------------------------------------------------------------------
; PRINTSTRING -- PRINT A NULL-TERMINATED PETSCII STRING VIA CHROUT.
; ---------------------------------------------------------------------------
PRINTSTRING:
    STA ZPDSTLO
    STY ZPDSTHI
    LDY #0
@LOOP:
    LDA (ZPDSTLO), Y
    BEQ @DONE
    JSR KERNALCHROUT
    INY
    JMP @LOOP
@DONE:
    RTS

; ---------------------------------------------------------------------------
; COMPACT MENU DATA. BLANK CELLS ARE PRODUCED BY CLEARMENUAREA; ONLY VISIBLE
; LINES ARE STORED. DESCRIPTOR ENTRIES ARE SOURCE POINTER, DESTINATION
; POINTER. THE STRING BYTES THEMSELVES LIVE IN THE GENERATED CONWAYMENU.S.
; ---------------------------------------------------------------------------
MENUDESCIDX:
    .BYTE 0

MENUDESCRIPTORS:
    .WORD MENUTITLE,       SCREEN + 0  * GRID_W + 10
    .WORD MENURULE,        SCREEN + 1  * GRID_W + 10
    .WORD MENUSELECT,      SCREEN + 3  * GRID_W + 2
    .WORD MENUPRESET1,     SCREEN + 4  * GRID_W + 4
    .WORD MENUPRESET2,     SCREEN + 5  * GRID_W + 4
    .WORD MENUPRESET3,     SCREEN + 6  * GRID_W + 4
    .WORD MENUPRESET4,     SCREEN + 7  * GRID_W + 4
    .WORD MENUPRESET5,     SCREEN + 8  * GRID_W + 4
    .WORD MENUPRESET6,     SCREEN + 9  * GRID_W + 4
    .WORD MENUPRESET7,     SCREEN + 10 * GRID_W + 4
    .WORD MENUPRESET8,     SCREEN + 11 * GRID_W + 4
    .WORD MENUPRESET9,     SCREEN + 12 * GRID_W + 4
    .WORD MENUCURRENT,     SCREEN + 14 * GRID_W + 2
    .WORD MENUBIRTHLABEL,  SCREEN + 15 * GRID_W + 2
    .WORD MENUSURVLABEL,   SCREEN + 16 * GRID_W + 2
    .WORD MENUCONTROLS1,   SCREEN + 18 * GRID_W + 2
    .WORD MENUCONTROLS2,   SCREEN + 19 * GRID_W + 2
    .WORD MENUCONTROLS3,   SCREEN + 20 * GRID_W + 2
    .WORD 0, 0

MENUARROWLO:
    .BYTE <(SCREEN + 4 * GRID_W + 2), <(SCREEN + 5 * GRID_W + 2)
    .BYTE <(SCREEN + 6 * GRID_W + 2), <(SCREEN + 7 * GRID_W + 2)
    .BYTE <(SCREEN + 8 * GRID_W + 2), <(SCREEN + 9 * GRID_W + 2)
    .BYTE <(SCREEN + 10 * GRID_W + 2), <(SCREEN + 11 * GRID_W + 2)
    .BYTE <(SCREEN + 12 * GRID_W + 2)
MENUARROWHI:
    .BYTE >(SCREEN + 4 * GRID_W + 2), >(SCREEN + 5 * GRID_W + 2)
    .BYTE >(SCREEN + 6 * GRID_W + 2), >(SCREEN + 7 * GRID_W + 2)
    .BYTE >(SCREEN + 8 * GRID_W + 2), >(SCREEN + 9 * GRID_W + 2)
    .BYTE >(SCREEN + 10 * GRID_W + 2), >(SCREEN + 11 * GRID_W + 2)
    .BYTE >(SCREEN + 12 * GRID_W + 2)

; ===========================================================================
; GENERATED + SPLIT-OUT SOURCES (TEXTUAL INCLUDE -- ONE GLOBAL NAMESPACE)
; ===========================================================================
.INCLUDE "CONWAYVER.S"
.INCLUDE "CONWAYMENU.S"
.INCLUDE "CONWAYGRID.S"
